def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = frozenset((r, c) for r in range(h) for c in range(w)
                      if grid[r][c] != 0)

    # The pieces are 2x2 squares and the three L-triomino orientations.
    pieces = [
        (1, ((0, 0), (0, 1), (1, 0), (1, 1))),
        (2, ((0, 1), (1, 0), (1, 1))),
        (3, ((0, 0), (0, 1), (1, 1))),
        (4, ((0, 0), (1, 0), (1, 1))),
    ]
    failed = set()

    def solve(remaining):
        if not remaining:
            return ()
        if remaining in failed:
            return None

        r, c = min(remaining)
        for color, shape in pieces:
            for ar in range(max(0, r - 1), min(r, h - 2) + 1):
                for ac in range(max(0, c - 1), min(c, w - 2) + 1):
                    placed = tuple((ar + dr, ac + dc) for dr, dc in shape)
                    if (r, c) not in placed or not all(p in remaining for p in placed):
                        continue
                    rest = remaining.difference(placed)
                    answer = solve(frozenset(rest))
                    if answer is not None:
                        return ((color, placed),) + answer

        failed.add(remaining)
        return None

    tiling = solve(cells)
    if tiling is None:
        return [row[:] for row in grid]

    out = [[0] * w for _ in range(h)]
    for color, placed in tiling:
        for r, c in placed:
            out[r][c] = color
    return out
